    out = open(f).read()
    sets, misses = [], []
    for l in out.splitlines():
        m = re.match(r"(declaration in top 3|question answer file in top 3|member questions|rust hits.*?|held-out questions|held-out members|held-out rust|report-only react-hook-form): (\d+/\d+)", l)
